namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

@page "/"
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>RecipeShare - Home</PageTitle>

<h1>Welcome to RecipeShare</h1>
<p>Discover and share delicious recipes with our community.</p>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in Recipes.GetCategories())
    {
        <a href="/recipes/@category.ToLower()" class="category-card">
            <h3>@category</h3>
            <p>@Recipes.GetByCategory(category).Count recipe(s)</p>
        </a>
    }
</div>

.category-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 1rem;
    margin-top: 1rem;
}

.category-card {
    display: block;
    padding: 1.5rem;
    border: 1px solid #ddd;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
}

.category-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}

.category-card h3 {
    margin: 0 0 0.5rem;
}

.category-card p {
    margin: 0;
    color: #666;
}

@page "/recipes/{CategoryName}"
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <ul class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <li>
                <a href="/recipe/@recipe.Id">@recipe.Title</a>
                @if (recipe.RatingCount > 0)
                {
                    <span class="rating">★ @recipe.AverageRating.ToString("F1")</span>
                }
            </li>
        }
    </ul>
}

<a href="/">← Back to categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeShare.Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = Recipes.GetByCategory(CategoryName);
    }
}

.recipe-list {
    list-style: none;
    padding: 0;
}

.recipe-list li {
    padding: 0.75rem 0;
    border-bottom: 1px solid #eee;
    display: flex;
    align-items: center;
    gap: 1rem;
}

.recipe-list a {
    font-size: 1.1rem;
}

.rating {
    color: #f5a623;
    font-weight: bold;
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p><strong>Category:</strong> @recipe.Category</p>

    @if (recipe.RatingCount > 0)
    {
        <p><strong>Rating:</strong> ★ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>
    }

    <h2>Ingredients</h2>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@step.TrimStart("0123456789. ".ToCharArray())</li>
        }
    </ol>

    <h3>Rate this recipe</h3>
    <StarRating RecipeId="recipe.Id" />

    <p><a href="/recipes/@recipe.Category.ToLower()">← Back to @recipe.Category</a></p>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService Recipes

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= selectedRating ? "selected" : "")"
              @onclick="() => Rate(star)">★</span>
    }
    @if (submitted)
    {
        <span class="thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedRating = stars;
        Recipes.AddRating(RecipeId, stars);
        submitted = true;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.25rem;
}

.star {
    font-size: 1.5rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s;
}

.star:hover,
.star.selected {
    color: #f5a623;
}

.thanks {
    margin-left: 0.5rem;
    color: #28a745;
    font-weight: bold;
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService Recipes
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

@if (successMessage is not null)
{
    <div class="alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="form-group">
        <label for="title">Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" />
    </div>

    <div class="form-group">
        <label for="category">Category</label>
        <InputSelect id="category" @bind-Value="model.Category" class="form-control">
            <option value="">-- Select a category --</option>
            <option value="Breakfast">Breakfast</option>
            <option value="Lunch">Lunch</option>
            <option value="Dinner">Dinner</option>
            <option value="Dessert">Dessert</option>
        </InputSelect>
    </div>

    <div class="form-group">
        <label for="ingredients">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="5" />
    </div>

    <div class="form-group">
        <label for="steps">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="5" />
    </div>

    <button type="submit" class="btn-submit">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps
        };

        Recipes.AddRecipe(recipe);
        successMessage = $"'{recipe.Title}' submitted successfully!";
        model = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = string.Empty;
    }
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: bold;
    margin-bottom: 0.25rem;
}

.form-control {
    width: 100%;
    max-width: 500px;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

.btn-submit {
    padding: 0.6rem 1.5rem;
    background-color: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-submit:hover {
    background-color: #0b5ed7;
}

.alert-success {
    padding: 0.75rem 1rem;
    background-color: #d1e7dd;
    color: #0f5132;
    border-radius: 4px;
    margin-bottom: 1rem;
}

