        new Recipe { Id = 8, Title = "Tiramisu", Category = "Dessert", Ingredients = "6 egg yolks\n3/4 cup sugar\n1 1/3 cups mascarpone\n2 cups heavy cream\nLadyfingers\nStrong coffee\nCocoa powder", Steps = "1. Whisk yolks and sugar until thick.\n2. Blend in mascarpone.\n3. Whip cream and fold in.\n4. Dip ladyfingers in coffee.\n5. Layer cookies and cream mixture.\n6. Dust with cocoa and refrigerate 4 hours." },
    };

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }
